@mcp.tool(annotations=ToolAnnotations(destructive_hint=True, open_world_hint=False))
def aitbc_zk_verify(
    job_id: Annotated[str | None, Field(description="Job ID whose receipt proof should be re-verified")],
    proof: Annotated[str | None, Field(description="Proof JSON, @file, or base64 string")],
    public_signals: Annotated[str | None, Field(description="Public signals JSON, @file, or base64 string")],
    circuit: Annotated[str | None, Field(description="Circuit name to verify against")],
    coordinator_url: Annotated[str | None, Field(description="Coordinator URL")],
    role: Annotated[NodeRole | None, Field(description="Node role to query.")] = None,
    host: Annotated[str | None, Field(description="Override the host for this call.")] = None,
    timeout: Annotated[int, Field(description="Timeout in seconds.", ge=5, le=600)] = 120,
    dry_run: Annotated[bool, Field(description="Show the command without executing it.")] = True,
    confirm: Annotated[bool, Field(description="Confirm the action.")] = False,
) -> str:
    """Verify a zero-knowledge proof against a circuit and public signals.."""
    options: dict[str, Any] = {}
    if job_id is not None:
        options["job-id"] = job_id
    if proof is not None:
        options["proof"] = proof
    if public_signals is not None:
        options["public-signals"] = public_signals
    if circuit is not None:
        options["circuit"] = circuit
    if coordinator_url is not None:
        options["coordinator-url"] = coordinator_url
    args = None
    command = _build_aitbc_cli_command(
        "zk",
        subcommand=["verify"],
        args=args,
        options=options,
        output_format="json",
    )
    if dry_run:
        return _json(_build_dry_run("Set dry_run=false to execute.", command))
    if not confirm:
        return _json(
            {
                "error": "Confirmation required",
                "command": command,
                "note": "This command may mutate state. Pass dry_run=false and confirm=true to execute.",
            }
        )
    target = _host_for_role(role, host)
    return _json(
        _run_aitbc_cli(
            target,
            "zk",
            subcommand=["verify"],
            args=args,
            options=options,
            output_format="json",
            timeout=timeout,
        )
    )
